sp_widget.script:
(function() { data.applicationId = $sp.getParameter("app_id") || ""; data.packageInfo = {};
  try { if (!data.applicationId) return; var gr = new GlideRecord("x_1433041_identi_0_application"); if (!gr.get(data.applicationId)) return;
    data.packageInfo = { name: gr.getValue("name"), type: gr.getDisplayValue("application_type"), integration: gr.getDisplayValue("integration_type"), criticality: gr.getDisplayValue("criticality"), completion: gr.getValue("completion_percent"), readiness: gr.getValue("readiness_score") };
  } catch (e) { gs.error("IBAR Build Package widget error: " + e.message); }
})();
